// Laravel (or any backend) asks n8n to place a real outbound phone call.
// RETELL_API_KEY stays in the n8n environment.
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
const call = body.call || body;
let secret = '';
let fromNumber = '';
let outboundId = 'agent_2603c7b2c919d2677273e30634';
let laravel = '';
let apiKeySet = false;
try {
  secret = $env.N8N_WEBHOOK_SECRET || '';
  fromNumber = $env.RETELL_FROM_NUMBER || '';
  if ($env.RETELL_OUTBOUND_AGENT_ID) outboundId = $env.RETELL_OUTBOUND_AGENT_ID;
  laravel = ($env.LARAVEL_API_URL || '').replace(/\/$/, '');
  apiKeySet = Boolean($env.RETELL_API_KEY);
} catch (err) {
  throw new Error('Allow n8n environment access so RETELL_API_KEY can be read.');
}
if (secret && (headers['x-n8n-secret'] || '') !== secret) throw new Error('X-N8N-Secret mismatch.');
if (!apiKeySet) throw new Error('Set RETELL_API_KEY in n8n (key name bdhousing-voice).');
if (call.mode && call.mode !== 'live') throw new Error('Refusing a payload that is not mode=live.');
if (call.active_call_exists) throw new Error('Active call already exists for this lead.');
if (call.consent_granted === false) throw new Error('Consent was not granted.');
const phone = String(call.phone || call.to_number || '').replace(/[\s()-]/g, '');
if (!/^\+[1-9]\d{7,14}$/.test(phone)) throw new Error('Phone must be E.164.');
if (!fromNumber) throw new Error('Set RETELL_FROM_NUMBER. Bind that Retell number to outbound agent agent_2603c7b2c919d2677273e30634.');
return [{ json: {
  laravel_call_id: call.id || '',
  forward_to_laravel: laravel && call.id ? 'yes' : 'no',
  laravel_url: laravel && call.id ? laravel + '/api/ai-calls/' + call.id + '/status' : '',
  url: 'https://api.retellai.com/v2/create-phone-call',
  payload: {
    from_number: fromNumber,
    to_number: phone,
    override_agent_id: outboundId,
    override_agent_version: 'latest_published',
    retell_llm_dynamic_variables: {
      customer_name: String(call.customer_name || ''),
      preferred_language: String(call.preferred_language || 'bn'),
      property_interest: String(call.property_interest || ''),
      call_purpose: String(call.call_purpose || 'Lead follow-up')
    },
    metadata: { source: 'bdhousing-n8n', workspace: 'BDHousing', org_id: 'org_b6zBp6LIqhl3aV7n', laravel_call_id: String(call.id || '') }
  }
} }];

const built = $('Build phone call').first().json;
const result = $input.first().json;
const failed = Boolean(result.error || result.message && !result.call_id);
return [{ json: {
  forward_to_laravel: built.forward_to_laravel,
  laravel_url: built.laravel_url,
  status_body: {
    status: failed ? 'failed' : 'initiated',
    provider_call_id: result.call_id || null,
    error_message: failed ? (result.message || result.error || 'Retell rejected the call') : null
  },
  retell: {
    provider: 'retell',
    call_id: result.call_id || null,
    call_status: result.call_status || (failed ? 'error' : 'registered'),
    agent_id: result.agent_id || null
  }
} }];
